CREATE TABLE IF NOT EXISTS growth_profiles (user_id TEXT PRIMARY KEY, xp INTEGER NOT NULL DEFAULT 0, level INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS xp_events (user_id TEXT NOT NULL, event_key TEXT NOT NULL, amount INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,event_key));
CREATE TABLE IF NOT EXISTS daily_growth (user_id TEXT NOT NULL, day TEXT NOT NULL, xp INTEGER NOT NULL DEFAULT 0, chat_turns INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS daily_tasks (user_id TEXT NOT NULL, day TEXT NOT NULL, task_key TEXT NOT NULL, progress INTEGER NOT NULL DEFAULT 0, target INTEGER NOT NULL DEFAULT 1, completed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day,task_key));
